panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:56px 60px 0;background:radial-gradient(circle at 10% 20%,rgba(214,62,118,.12),transparent 45%),radial-gradient(circle at 92% 80%,rgba(245,197,24,.16),transparent 48%),var(--cream)}
.k{font-size:29px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:60px;font-weight:900;line-height:1.25;text-align:center;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.note{position:absolute;left:60px;right:60px;bottom:40px;font-size:22px}
.tbl{margin-top:34px;background:#fff;border-radius:26px;padding:14px 28px;box-shadow:0 20px 40px -26px rgba(30,18,25,.4)}
.h,.r{display:grid;align-items:center;gap:12px}
.h{font-size:22px;color:var(--ink-2);font-weight:700;padding:8px 0;border-bottom:2px solid #eadde3}
.r{padding:20px 0;border-bottom:2px dashed #eadde3}.r:last-child{border-bottom:0}
.nm img{height:50px;max-width:260px;object-fit:contain}.nm.tx{font-size:31px;font-weight:900}
.c{font-size:26px;font-weight:700;text-align:right}.c.hot{color:#D63E76;font-weight:900}.c.ok{color:#2f7d4f}
.yen{text-align:right;font-size:40px;font-weight:900}.yen.hot{color:#D63E76}
.one{margin-top:28px;text-align:center;font-size:31px;font-weight:700;background:#46293A;color:#fff;border-radius:18px;padding:18px 16px}.one b{color:#F5C518;font-weight:900}
.r{grid-template-columns:110px 1fr 260px;padding:16px 0}.nm img{height:64px;width:100px;object-fit:contain;border-radius:14px}.nm.tx small{display:block;font-size:20px;color:var(--ink-2);font-weight:700}.r.vs{background:#fff3f7;margin:0 -28px;padding:18px 28px;border-radius:0 0 26px 26px}
